sp_widget.client_script:
api.controller = function($scope, spUtil, $rootScope) {
	var c = this;

	console.log(c.data.fields[0].name);

	c.selectedField = c.data.fields[0].name;
	c.searchText = '';
	c.previousSearchText = ''; 
	var searchQuery;


	$scope.Selectinputchange = function(){
		c.searchText = "";
		$rootScope.$broadcast('searchCriteriaChanged', c.selectedField + 'LIKE' +c.searchText);

	}


	c.onSearchChange = function() {
		if (c.selectedField) {

			$rootScope.$broadcast('searchCriteriaChanged', c.selectedField + 'LIKE' +c.searchText);

			/*   if (c.searchText == '') {
        $rootScope.$broadcast('searchCriteriaChanged', '');
      } 

      else if (c.searchText.length < c.previousSearchText.length) {

         searchQuery = c.selectedField + 'LIKE' + c.previousSearchText;
        $rootScope.$broadcast('searchCriteriaChanged', searchQuery);
      } 

      else {
         searchQuery = c.selectedField + 'LIKE' + c.searchText;
        $rootScope.$broadcast('searchCriteriaChanged', searchQuery);
      }
			*/

			// Update the previous search text after broadcasting
			c.previousSearchText = c.searchText;
		}
	};
};

sp_widget.css:
.search-widget {
  margin-bottom: 1rem;
  padding: 1rem;
  background-color: #f8f9fa;
  border-radius: .5rem;
  box-shadow: 0rem 0rem 1rem rgba(0, 0, 0, .1);
  display: flex;
  /* align-items: center; */
  width: 52%;
}
#fieldDropdown{
  width:25rem;
}

.search-widget .form-label {
  font-weight: bold;
  margin-bottom: 0;
}

.search-widget .form-control {
  padding: 8px;
  margin-bottom: 0;
  border: 1px solid #ced4da;
  border-radius: 4px;
}

.search-widget .form-control + .form-control {
  margin-left: 10px;
}

.me-2 {
  margin-right: 10px;
}

sp_widget.script:
(function($sp) {
  data.table = $sp.getValue('table'); // Get the table name
  var fields = $sp.getValue('field_list').split(','); // Split the field list into an array
  data.fields = [];

	function getFieldName(field) {
    var dictgr = new GlideRecord('sys_dictionary');
    var reftable = '';
    if (field.includes(".")) {
        var f = field.split(".");
        var fetchrefgr = new GlideRecord('sys_dictionary');
        fetchrefgr.addQuery('element', f[0]);
        fetchrefgr.addQuery('name', data.table);

        fetchrefgr.query();

        if (fetchrefgr.next()) {
            reftable = fetchrefgr.getValue('reference');
        }

        dictgr.addQuery('element', f[1]);
        dictgr.addQuery('name', reftable);
    } else {
        dictgr.addQuery('element', field);
        dictgr.addQuery('name', data.table);
    }

    dictgr.query();
    if (dictgr.next()) {
        return dictgr.getValue('column_label');
    } else {
        var perenttable = '';
        var perenttable1 = '';
        var db = new GlideRecord('sys_db_object');
        db.addQuery('name', reftable);
        db.query();
        if (db.next()) {
            perenttable = db.getValue('super_class');
        }
        var db1 = new GlideRecord('sys_db_object');
        db1.addEncodedQuery('sys_idSTARTSWITH' + perenttable);
        db1.query();
        if (db1.next()) {
            perenttable1 = db1.getValue('name');
        }
        var dictgr1 = new GlideRecord('sys_dictionary');
        var fields = field.split(".");
        dictgr1.addQuery('element', fields[1]);
        dictgr1.addQuery('name', perenttable1);
        dictgr1.query();
        if (dictgr1.next()) {
            return dictgr1.getValue('column_label');
        }
    }
}
  fields.forEach(function(field) {
    var label = getFieldName(field)

    data.fields.push({
      name: label,
      label: field
		});
  });
})($sp);
